SELECT SUM(tolls_amount) AS total_tolls
FROM yellow_tripdata
WHERE DATE_PART('year', tpep_pickup_datetime) = 2023 AND DATE_PART('month', tpep_pickup_datetime) = 3;

SELECT CAST(SUM(CASE WHEN payment_type = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS cash_percentage
FROM yellow_tripdata
WHERE EXTRACT(YEAR FROM tpep_pickup_datetime) = 2023;

SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY trip_duration_minutes) AS percentile_90
FROM yellow_tripdata
WHERE EXTRACT(YEAR FROM tpep_pickup_datetime) = 2023;

SELECT COUNT(*) AS trip_count
FROM yellow_tripdata
WHERE payment_type = 'Credit card' AND EXTRACT(YEAR FROM tpep_pickup_datetime) = 2023;

SELECT SUM(tolls_amount) AS total_tolls
FROM yellow_tripdata
WHERE EXTRACT(YEAR FROM tpep_pickup_datetime) = 2023 AND EXTRACT(MONTH FROM tpep_pickup_datetime) = 3;

SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY trip_duration_minutes) AS percentile_90th
FROM yellow_tripdata
WHERE EXTRACT(YEAR FROM tpep_pickup_datetime) = 2023;

SELECT COUNT(*) AS num_trips
FROM fct_trips
WHERE payment_type = 'Credit Card' AND EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT AVG(tip_amount) / 100 AS average_tip_usd
FROM fct_trips
WHERE YEAR(pickup_at) = 2023 AND payment_type = 'Credit Card';

SELECT SUM(tolls_amount) AS total_tolls
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023 AND EXTRACT(MONTH FROM pickup_at) = 3;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE trip_distance_miles > 10 AND EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT CAST(SUM(CASE WHEN payment_type = 'Cash' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS cash_payment_percentage
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY trip_duration_minutes) AS percentile_90th
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT COUNT(*) AS card_fare_count
FROM fct_trips
WHERE payment_type = 'Credit card';

SELECT AVG(tip_amount) AS avg_tip
FROM fct_trips
WHERE payment_type = 'Credit card';

SELECT SUM(tolls_amount) AS total_tolls
FROM fct_trips
WHERE month_key = '2023-03';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE trip_distance_miles > 10;

SELECT AVG(trip_count) AS avg_trips_per_day
FROM trips_hourly_demand
WHERE is_weekend = TRUE;
